import { useState, useEffect } from 'react';
import type { ReactElement } from 'react';
import type { Task } from '../../types';
import { getTasks } from '../../api';
import './TaskBoard.css';

const SKELETON_COUNT = 4;

export function TaskBoard(): ReactElement {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks().then(setTasks).catch(() => { setTasks([]); });
  }, []);

  const isLoading = tasks === null;
  const isEmpty = tasks !== null && tasks.length === 0;
  const taskCount = tasks !== null ? tasks.length : 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        <span
          className="task-board-badge"
          aria-label={isLoading ? 'loading' : `${taskCount} tasks`}
        >
          {isLoading ? '–' : taskCount}
        </span>
      </header>
      <div className="task-board-filter-bar" role="search" aria-label="Filter tasks" />
      <div className="task-board-main">
        {isLoading && (
          <ul className="task-list" aria-label="Loading tasks">
            {Array.from({ length: SKELETON_COUNT }, (_, i) => (
              <li key={i} className="task-card task-card-skeleton">
                <div className="skeleton-title" />
                <div className="skeleton-meta" />
              </li>
            ))}
          </ul>
        )}
        {isEmpty && (
          <p className="task-board-empty">No tasks yet.</p>
        )}
        {!isLoading && !isEmpty && tasks !== null && (
          <ul className="task-list" aria-label="Tasks">
            {tasks.map((task) => (
              <li key={task.id} className="task-card">
                <span className="task-card-title">{task.title}</span>
                <span className="task-card-status">{task.status}</span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
